import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {JSDOM} from 'jsdom';
const html=readFileSync(new URL('../dist/index.html',import.meta.url),'utf8');
const code=readFileSync(new URL('../dist/app.js',import.meta.url),'utf8');
const tick=()=>new Promise(r=>setTimeout(r,15));
async function setup(seed=true,android=false){
 const dom=new JSDOM(html,{runScripts:'outside-only',url:'https://example.com'}),w=dom.window,copied=[];Object.defineProperty(w.navigator,'clipboard',{configurable:true,value:{writeText:async text=>copied.push(text)}});
 const p='11111111-1111-4111-8111-111111111111',t='22222222-2222-4222-8222-222222222222';
 const db={projects:seed?[{id:p,name:'Launch',notes:'',position:1024}]:[],tasks:seed?[{id:t,project_id:p,name:'Plan launch',notes:'',assignee:'',status:'assigned',position:1024,start_date:null,end_date:null}]:[],cells:[],project_cells:[],comments:[]};
 let serial=0;w.fetch=async(url,init)=>{const u=new URL(url),table=u.pathname.split('/').at(-1).replace('gant02_20261024_',''),id=u.searchParams.get('id')?.slice(3);let rows=db[table];if(table==='quick_add'){const b=JSON.parse(init.body),existing=db.tasks.find(t=>t.id===b.p_task_id);if(existing)return {ok:true,status:200,json:async()=>structuredClone({project:db.projects.find(p=>p.id===existing.project_id),task:existing})};let project=db.projects.find(p=>p.name.trim().toLowerCase()==='general');if(!project){project={id:'general-'+(++serial),name:'General',position:Math.max(0,...db.projects.map(p=>p.position))+1024,notes:''};db.projects.push(project);}const task={id:b.p_task_id,project_id:project.id,name:b.p_name.trim(),position:Math.max(0,...db.tasks.map(t=>t.position))+1024,status:'assigned',assignee:'',notes:'',start_date:b.p_day,end_date:b.p_day};db.tasks.push(task);db.cells.push({task_id:task.id,day:b.p_day,status:'assigned'});return {ok:true,status:200,json:async()=>structuredClone({project,task})};}if(table==='create_task'){const b=JSON.parse(init.body),task={id:'new-'+(++serial),project_id:b.p_project_id,name:b.p_name,position:b.p_position,notes:'',assignee:'',status:'assigned',start_date:null,end_date:null};db.tasks.push(task);db.cells.push({task_id:task.id,day:b.p_day,status:'assigned'});return {ok:true,status:200,json:async()=>structuredClone([task])};}if(table==='move_cell'){const b=JSON.parse(init.body),fromTable=b.p_source_kind==='project'?'project_cells':'cells',toTable=b.p_target_kind==='project'?'project_cells':'cells',fromKey=b.p_source_kind==='project'?'project_id':'task_id',toKey=b.p_target_kind==='project'?'project_id':'task_id';for(const [table,key,id,day,status] of [[fromTable,fromKey,b.p_source_id,b.p_source_day,null],[toTable,toKey,b.p_target_id,b.p_target_day,b.p_status]]){const existing=db[table].find(c=>c[key]===id&&c.day===day);if(existing)existing.status=status;else db[table].push({[key]:id,day,status});}return {ok:true,status:204};}if(init.method==='GET'){if(table==='comments'){const project=u.searchParams.get('project_id')?.slice(3),task=u.searchParams.get('task_id')?.slice(3);rows=rows.filter(c=>(!project||c.project_id===project)&&(!task||c.task_id===task)).sort((a,b)=>b.created_at.localeCompare(a.created_at));const offset=Number(u.searchParams.get('offset')||0);rows=rows.slice(offset,offset+1000);}return {ok:true,status:200,json:async()=>structuredClone(rows)};}const body=init.body?JSON.parse(init.body):null;let result=[];if(init.method==='POST'&&table==='comments'){const existing=rows.find(c=>c.id===body.id);if(existing)Object.assign(existing,body);else rows.push({...body});return {ok:true,status:200,json:async()=>structuredClone([rows.find(c=>c.id===body.id)])};}if(init.method==='POST'&&(table==='cells'||table==='project_cells')){for(const x of body){const existing=rows.find(c=>c.task_id===x.task_id&&c.project_id===x.project_id&&c.day===x.day);if(existing)Object.assign(existing,x);else rows.push(x);}return {ok:true,status:200,json:async()=>structuredClone(body)};}if(init.method==='POST'){const x={id:'new-'+(++serial),notes:'',assignee:'',status:'assigned',start_date:null,end_date:null,...body};rows.push(x);result=[x];}if(init.method==='PATCH'){const x=rows.find(x=>x.id===id);if(x){Object.assign(x,body);result=[x];}}if(init.method==='DELETE'){result=rows.filter(x=>x.id===id);db[table]=rows.filter(x=>x.id!==id);if(table==='projects'){db.tasks=db.tasks.filter(x=>x.project_id!==id);db.project_cells=db.project_cells.filter(x=>x.project_id!==id);db.cells=db.cells.filter(x=>db.tasks.some(t=>t.id===x.task_id));db.comments=db.comments.filter(c=>c.project_id!==id&&(!c.task_id||db.tasks.some(t=>t.id===c.task_id)));}if(table==='tasks'){db.cells=db.cells.filter(x=>x.task_id!==id);db.comments=db.comments.filter(c=>c.task_id!==id);}}return {ok:true,status:200,json:async()=>structuredClone(result)};};
 if(android)Object.defineProperty(w.navigator,'userAgent',{configurable:true,value:'Mozilla/5.0 (Linux; Android 15; Pixel 9) AppleWebKit/537.36 Chrome/140.0 Mobile Safari/537.36'});
 w.confirm=()=>true;w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;};w.HTMLElement.prototype.setPointerCapture=()=>{};w.HTMLElement.prototype.hasPointerCapture=()=>false;
 w.eval(code);await tick();return {w,db,p,t,copied,close:()=>w.close(),$:id=>w.document.getElementById(id)};
}
function pointer(w,el,type,x,y=10){el.dispatchEvent(new w.MouseEvent(type,{bubbles:true,button:0,clientX:x,clientY:y}));}
async function enterInline(a,type,name,projectId){const input=[...a.w.document.querySelectorAll('.inline-create')].find(x=>x.dataset.create===type&&(!projectId||x.dataset.projectId===projectId));input.value=name;input.dispatchEvent(new a.w.Event('input',{bubbles:true}));input.dispatchEvent(new a.w.KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));await tick();}
test('blank rows create projects and tasks without an empty-state card',async()=>{const a=await setup(false);try{const {w,$,db}=a;assert.doesNotMatch($('grid').textContent,/Make room|Create your first project/);assert.equal(w.document.querySelectorAll('.inline-create').length,1);await enterInline(a,'project','New project');assert.equal(db.projects[0].name,'New project');assert.equal(w.document.activeElement.dataset.create,'task');await enterInline(a,'task','First task');assert.equal(db.tasks[0].project_id,db.projects[0].id);assert.equal(w.document.activeElement.dataset.create,'task');assert.equal(w.document.activeElement.value,'');assert.equal($('summary'),null);assert.equal(w.document.querySelectorAll('.task-row').length,1);}finally{a.close();}});
test('color controls follow All with no schedule or color-a-date display',async()=>{const a=await setup();try{const {w,$}=a;assert.equal($('days-filter').nextElementSibling,$('paint-tools'));assert.equal(w.document.querySelector('[data-paint="schedule"]'),null);assert.doesNotMatch(w.document.body.textContent,/Color a date|Schedule bars/);assert.deepEqual([...$('paint-tools').querySelectorAll('[data-paint]')].map(x=>x.dataset.paint),['assigned','in_progress','done','erase']);}finally{a.close();}});
test('notes panel removes task metadata and description edits preserve stored values',async()=>{const a=await setup();try{const {w,$,db}=a;Object.assign(db.tasks[0],{status:'in_progress',assignee:'Elliot',start_date:'2026-11-04',end_date:'2026-11-05'});$('refresh').click();await tick();w.document.querySelector('[data-open]').click();for(const id of ['task-fields','detail-project','detail-status','detail-assignee','detail-start','detail-end','clear-dates'])assert.equal($(id),null);assert.equal(w.document.querySelector('.notes-label').textContent,'Description');$('notes').innerHTML='<p>Larger description</p>';$('detail-form').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.equal(db.tasks[0].notes,'<p>Larger description</p>');assert.equal(db.tasks[0].status,'in_progress');assert.equal(db.tasks[0].assignee,'Elliot');assert.equal(db.tasks[0].start_date,'2026-11-04');assert.equal(db.tasks[0].end_date,'2026-11-05');}finally{a.close();}});
test('detail notes keep formatting and remove active markup',async()=>{const a=await setup();try{const {w,$,db}=a;w.document.querySelector('[data-open]').click();$('notes').innerHTML='<p><b>Ready</b> for launch</p><script>alert(1)</script><a href="javascript:alert(1)" onclick="bad()">bad link</a>';$('detail-form').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.match(db.tasks[0].notes,/<b>Ready<\/b>/);assert.doesNotMatch(db.tasks[0].notes,/script|onclick|javascript/);assert.equal($('drawer').hidden,false);assert.match($('detail-message').textContent,/Saved automatically/);}finally{a.close();}});
test('drag task name moves it into another project',async()=>{const a=await setup();try{const {w,$,db}=a;await enterInline(a,'project','Second project');const e=new w.Event('dragstart',{bubbles:true});e.dataTransfer={setData(){}};w.document.querySelector('[data-open]').dispatchEvent(e);const target=w.document.querySelectorAll('.project-row')[1];target.dispatchEvent(new w.Event('drop',{bubbles:true,cancelable:true}));await tick();assert.equal(db.tasks[0].project_id,db.projects[1].id);}finally{a.close();}});
test('blank detail names are blocked and search filters rows',async()=>{const a=await setup();try{const {w,$,db}=a;w.document.querySelector('[data-open]').click();$('detail-name').value='';$('detail-form').dispatchEvent(new w.Event('submit',{cancelable:true}));await tick();assert.match($('detail-message').textContent,/Enter a name/);assert.equal(db.tasks[0].name,'Plan launch');$('detail-name').value='Plan launch';$('close-drawer').click();await tick();$('search').value='unmatched';$('search').dispatchEvent(new w.Event('input'));assert.match($('grid').textContent,/No matching tasks/);}finally{a.close();}});
test('blank inputs ignore whitespace, cancel with Escape and save once on blur',async()=>{const a=await setup();try{const {w,db}=a;let input=w.document.querySelector('[data-create="task"]');input.value='   ';input.dispatchEvent(new w.FocusEvent('focusout',{bubbles:true}));await tick();assert.equal(db.tasks.length,1);input.value='Cancelled';input.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));assert.equal(input.value,'');input.value='Save on Tab';input.dispatchEvent(new w.Event('input',{bubbles:true}));input.dispatchEvent(new w.FocusEvent('focusout',{bubbles:true}));input.dispatchEvent(new w.FocusEvent('focusout',{bubbles:true}));await tick();assert.equal(db.tasks.length,2);assert.equal(db.tasks[1].name,'Save on Tab');}finally{a.close();}});
test('calendar header has spreadsheet letters, vertical month, weekdays and day strip',async()=>{const a=await setup();try{const {w}=a,cols=w.document.querySelectorAll('.date-column');assert.equal(cols.length,120);assert.ok(cols[0].classList.contains('today'));assert.equal(cols[0].querySelector('.sheet-letter').textContent,'B');assert.equal(cols[25].querySelector('.sheet-letter').textContent,'AA');assert.match(cols[0].querySelector('.vertical-month').textContent,/^[A-Za-z]{3}$/);assert.match(cols[0].querySelector('.weekday').textContent,/^(MON|TUE|WED|THU|FRI|SAT|SUN)$/);assert.match(cols[0].querySelector('.day-number').textContent,/^[0-9]{2}$/);}finally{a.close();}});
test('failed inline creation retains typed name for retry',async()=>{const a=await setup();try{const {w,db,$}=a;w.fetch=async()=>({ok:false,status:503,json:async()=>({message:'Connection interrupted'})});await enterInline(a,'task','Keep this draft');const input=w.document.querySelector('[data-create="task"]');assert.equal(input.value,'Keep this draft');assert.equal(input.disabled,false);assert.equal(db.tasks.length,1);assert.match($('error').textContent,/Connection interrupted/);}finally{a.close();}});

test('paint independent dates in three colors and clear a square',async()=>{const a=await setup();try{const {w,db,$}=a;const square=i=>w.document.querySelector(`.task-timeline [data-index="${i}"]`);async function paint(i,mode){w.document.querySelector(`[data-paint="${mode}"]`).click();pointer(w,square(i),'pointerdown',i*26+5);pointer(w,w.document.querySelector('.task-timeline'),'pointerup',i*26+5);await tick();}await paint(2,'assigned');await paint(4,'in_progress');await paint(7,'done');assert.deepEqual(db.cells.map(c=>c.status),['assigned','in_progress','done']);assert.equal(db.tasks[0].start_date,null);assert.match(square(2).className,/assigned/);assert.match(square(4).className,/in_progress/);assert.match(square(7).className,/done/);await paint(4,'erase');assert.equal(db.cells.find(c=>c.day===square(4).dataset.day).status,null);assert.doesNotMatch(square(4).className,/in_progress/);$('refresh').click();await tick();assert.match(square(7).className,/done/);}finally{a.close();}});
test('paint a drag range and retain other date colors',async()=>{const a=await setup();try{const {w,db}=a;const line=()=>w.document.querySelector('.task-timeline');pointer(w,line(),'pointerdown',26);pointer(w,line(),'pointermove',104);pointer(w,line(),'pointerup',104);await tick();assert.equal(db.cells.length,4);w.document.querySelector('[data-paint="done"]').click();pointer(w,line(),'pointerdown',52);pointer(w,line(),'pointerup',52);await tick();assert.equal(db.cells.length,4);assert.equal(db.cells.filter(c=>c.status==='done').length,1);assert.equal(db.cells.filter(c=>c.status==='assigned').length,3);}finally{a.close();}});
test('paint failure restores persisted colors and exposes an error',async()=>{const a=await setup();try{const {w,$,db}=a,original=w.fetch;w.fetch=async(url,init)=>init.method==='POST'?{ok:false,status:503,json:async()=>({message:'Save unavailable'})}:original(url,init);const line=w.document.querySelector('.task-timeline');pointer(w,line,'pointerdown',52);pointer(w,line,'pointerup',52);await tick();assert.equal(db.cells.length,0);assert.match($('error').textContent,/Save unavailable/);assert.doesNotMatch(w.document.querySelector('.task-timeline [data-index="2"]').className,/assigned/);}finally{a.close();}});

function dragItem(w,source,target,y=-1){const e=new w.Event('dragstart',{bubbles:true,cancelable:true});e.dataTransfer={setData(){}};source.dispatchEvent(e);target.dispatchEvent(new w.MouseEvent('drop',{bubbles:true,cancelable:true,clientY:y}));}
test('project name dragging reorders whole groups before, after and to end',async()=>{const a=await setup();try{const {w,db,p}=a;await enterInline(a,'project','Second');await enterInline(a,'project','Third');const second=db.projects[1].id,third=db.projects[2].id;const name=id=>w.document.querySelector(`[data-open-project="${id}"]`),row=id=>w.document.querySelector(`.project-row[data-project="${id}"]`),order=()=>[...w.document.querySelectorAll('.project-row')].map(x=>x.dataset.project);dragItem(w,name(third),row(p));await tick();assert.deepEqual(order(),[third,p,second]);assert.ok(db.projects.find(x=>x.id===third).position<db.projects.find(x=>x.id===p).position);dragItem(w,name(third),row(second),1);await tick();assert.deepEqual(order(),[p,second,third]);dragItem(w,name(p),w.document.querySelector('.new-project-row'));await tick();assert.deepEqual(order(),[second,third,p]);assert.equal(db.tasks[0].project_id,p);assert.ok(w.document.querySelector(`[data-task="${db.tasks[0].id}"]`));}finally{a.close();}});
test('task name dragging supports both sides of another task without a handle',async()=>{const a=await setup();try{const {w,db,t}=a;await enterInline(a,'task','Second task');const second=db.tasks[1].id;assert.equal(w.document.querySelector('.grip'),null);assert.equal(w.document.querySelector('.project-count'),null);assert.equal(w.document.querySelector('.project-add'),null);const name=id=>w.document.querySelector(`[data-open="${id}"]`),row=id=>w.document.querySelector(`[data-task="${id}"]`),order=()=>[...w.document.querySelectorAll('.task-row')].map(x=>x.dataset.task);dragItem(w,name(second),row(t));await tick();assert.deepEqual(order(),[second,t]);dragItem(w,name(second),row(t),1);await tick();assert.deepEqual(order(),[t,second]);}finally{a.close();}});
test('failed project reorder restores original order and leaves tasks intact',async()=>{const a=await setup();try{const {w,db,p,$}=a;await enterInline(a,'project','Second');const second=db.projects[1].id,original=w.fetch;w.fetch=async(url,init)=>init.method==='PATCH'?{ok:false,status:503,json:async()=>({message:'Reorder unavailable'})}:original(url,init);dragItem(w,w.document.querySelector(`[data-open-project="${second}"]`),w.document.querySelector(`.project-row[data-project="${p}"]`));await tick();assert.deepEqual([...w.document.querySelectorAll('.project-row')].map(x=>x.dataset.project),[p,second]);assert.equal(db.tasks[0].project_id,p);assert.match($('error').textContent,/Reorder unavailable/);}finally{a.close();}});

test('project row supports independent colors, clearing and collapsed projects',async()=>{const a=await setup();try{const {w,db,p,$}=a;const line=()=>w.document.querySelector('.project-row .paint-timeline');w.document.querySelector('[data-paint="done"]').click();pointer(w,line(),'pointerdown',78);pointer(w,line(),'pointerup',78);await tick();assert.equal(db.project_cells[0].project_id,p);assert.equal(db.project_cells[0].status,'done');assert.equal(db.cells.length,0);w.document.querySelector('[data-collapse]').click();const cell=w.document.querySelector('.project-row [data-index="3"]');assert.match(cell.className,/done/);$('refresh').click();await tick();assert.match(w.document.querySelector('.project-row [data-index="3"]').className,/done/);}finally{a.close();}});
test('drag a colored square to another date and between project and task rows',async()=>{const a=await setup();try{const {w,db}=a;const task=()=>w.document.querySelector('.task-timeline'),square=(kind,i)=>w.document.querySelector(`[data-kind="${kind}"].date-square[data-index="${i}"]`);pointer(w,task(),'pointerdown',52);pointer(w,task(),'pointerup',52);await tick();dragItem(w,square('task',2),square('task',5));await tick();assert.equal(db.cells.find(c=>c.day===square('task',2).dataset.day).status,null);assert.equal(db.cells.find(c=>c.day===square('task',5).dataset.day).status,'assigned');dragItem(w,square('task',5),square('project',8));await tick();assert.equal(db.project_cells[0].status,'assigned');assert.match(square('project',8).className,/assigned/);dragItem(w,square('project',8),square('task',10));await tick();assert.equal(db.project_cells[0].status,null);assert.match(square('task',10).className,/assigned/);}finally{a.close();}});
test('failed square move keeps both source and destination colors',async()=>{const a=await setup();try{const {w,$}=a;const line=()=>w.document.querySelector('.task-timeline'),square=i=>w.document.querySelector(`.task-timeline [data-index="${i}"]`);pointer(w,line(),'pointerdown',52);pointer(w,line(),'pointerup',52);await tick();w.document.querySelector('[data-paint="done"]').click();pointer(w,line(),'pointerdown',130);pointer(w,line(),'pointerup',130);await tick();const original=w.fetch;w.fetch=async(url,init)=>url.includes('/rpc/')?{ok:false,status:503,json:async()=>({message:'Move unavailable'})}:original(url,init);dragItem(w,square(2),square(5));await tick();assert.match(square(2).className,/assigned/);assert.match(square(5).className,/done/);assert.match($('error').textContent,/Move unavailable/);}finally{a.close();}});

const pause=ms=>new Promise(r=>setTimeout(r,ms));
function offsetDate(day,n){return new Date(+new Date(day+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);}
test('separate Brotherhood meeting dates leave gaps blank even with old start/finish dates',async()=>{const a=await setup();try{const {w,db,$}=a;const first=w.document.querySelector('.date-column').dataset.day;db.tasks[0].name='Brotherhood meeting';db.tasks[0].start_date=offsetDate(first,2);db.tasks[0].end_date=offsetDate(first,18);$('refresh').click();await tick();const line=()=>w.document.querySelector('.task-timeline'),square=i=>w.document.querySelector(`.task-timeline [data-index="${i}"]`);for(const index of [2,10,18]){pointer(w,line(),'pointerdown',index*26+5);pointer(w,line(),'pointerup',index*26+5);await tick();}assert.equal(db.cells.length,3);for(const index of [2,10,18])assert.match(square(index).className,/assigned/);for(const index of [3,4,9,11,17])assert.doesNotMatch(square(index).className,/assigned|in_progress|done/);$('refresh').click();await tick();assert.doesNotMatch(square(11).className,/assigned|in_progress|done/);}finally{a.close();}});
test('date hover text counts days from today with Sunday-only shading and no today line',async()=>{const a=await setup();try{const {w}=a,number=w.document.querySelector('.date-column.today .day-number');assert.match(number.title,/^0 days out · [0-9]{2}-[0-9]{2} [A-Za-z]{3}$/);assert.equal(w.document.querySelector('.titlebar'),null);const bands=[...w.document.querySelectorAll('.weekend-band')];assert.ok(bands.length>0);assert.ok(bands.every(b=>new Date(b.dataset.day+'T12:00:00Z').getUTCDay()===0));assert.equal(w.document.querySelector('.today-line'),null);assert.equal(w.document.querySelector('.date-column.weekend'),null);const day=w.document.querySelectorAll('.day-number')[3];assert.match(day.title,/^3 days out · [0-9]{2}-[0-9]{2} [A-Za-z]{3}$/);const blank=w.document.querySelector('.task-timeline [data-index="3"]').title;assert.match(blank,/^[1-9][0-9]?-[0-9]{2} (Sun|Mon|Tue|Wed|Thu|Fri|Sat) · 3$/);const line=w.document.querySelector('.task-timeline');pointer(w,line,'pointerdown',3*26+5);pointer(w,line,'pointerup',3*26+5);await tick();assert.match(w.document.querySelector('.task-timeline [data-index="3"]').title,/^[1-9][0-9]?-[0-9]{2} (Sun|Mon|Tue|Wed|Thu|Fri|Sat) · 3$/);w.document.querySelector('[data-paint="erase"]').click();const updatedLine=w.document.querySelector('.task-timeline');pointer(w,updatedLine,'pointerdown',3*26+5);pointer(w,updatedLine,'pointerup',3*26+5);await tick();assert.equal(w.document.querySelector('.task-timeline [data-index="3"]').title,blank);}finally{a.close();}});
test('day filter defaults to All and combines colored date windows, projects and statuses',async()=>{const a=await setup();try{const {w,db,p,t,$}=a,today=w.document.querySelector('.date-column.today').dataset.day,base=db.tasks[0];db.tasks=[{...base,name:'Today',id:t},{...base,name:'Boundary',id:'boundary'},{...base,name:'Later',id:'later'},{...base,name:'Past',id:'past'}];db.projects.push({id:'project-only',name:'Project date only',position:2048,notes:''},{id:'empty-project',name:'No dates',position:3072,notes:''});db.cells=[{task_id:t,day:today,status:'assigned'},{task_id:'boundary',day:offsetDate(today,3),status:'done'},{task_id:'later',day:offsetDate(today,4),status:'done'},{task_id:'past',day:offsetDate(today,-1),status:'done'}];db.project_cells=[{project_id:'project-only',day:offsetDate(today,2),status:'done'}];$('refresh').click();await tick();assert.equal($('days-filter').value,'all');assert.deepEqual([...$('days-filter').options].map(x=>x.textContent),['All','1 Day','3 Days','7 Days','30 Days']);const ids=()=>[...w.document.querySelectorAll('.task-row')].map(x=>x.dataset.task),projectIds=()=>[...w.document.querySelectorAll('.project-row')].map(x=>x.dataset.project);$('days-filter').value='3';$('days-filter').dispatchEvent(new w.Event('change'));assert.deepEqual(ids(),[t,'boundary']);assert.deepEqual(projectIds(),[p,'project-only']);$('status-filter').value='done';$('status-filter').dispatchEvent(new w.Event('change'));assert.deepEqual(ids(),['boundary']);assert.deepEqual(projectIds(),[p,'project-only']);$('days-filter').value='1';$('days-filter').dispatchEvent(new w.Event('change'));assert.equal(ids().length,0);assert.equal(projectIds().length,0);$('status-filter').value='';$('days-filter').value='7';$('days-filter').dispatchEvent(new w.Event('change'));assert.deepEqual(ids(),[t,'boundary','later']);$('days-filter').value='all';$('days-filter').dispatchEvent(new w.Event('change'));assert.equal(ids().length,4);assert.equal(projectIds().length,3);}finally{a.close();}});
test('notes autosave without submit and flush immediately when closing',async()=>{const a=await setup();try{const {w,db,$}=a;w.document.querySelector('[data-open]').click();assert.equal($('save-detail'),null);$('notes').innerHTML='<p><b>Recurring meeting</b></p>';$('notes').dispatchEvent(new w.Event('input',{bubbles:true}));await pause(550);assert.equal(db.tasks[0].notes,'<p><b>Recurring meeting</b></p>');assert.match($('detail-message').textContent,/Saved automatically/);$('notes').innerHTML='<p>Latest agenda</p>';$('notes').dispatchEvent(new w.Event('input',{bubbles:true}));$('close-drawer').click();await tick();assert.equal(db.tasks[0].notes,'<p>Latest agenda</p>');assert.equal($('drawer').hidden,true);}finally{a.close();}});
test('typing during an autosave keeps the latest note and project notes autosave too',async()=>{const a=await setup();try{const {w,db,$}=a,original=w.fetch;w.fetch=async(url,init)=>{if(init.method==='PATCH')await pause(90);return original(url,init);};w.document.querySelector('[data-open]').click();$('notes').innerHTML='First draft';$('notes').dispatchEvent(new w.Event('input',{bubbles:true}));await pause(520);$('notes').innerHTML='Second draft';$('notes').dispatchEvent(new w.Event('input',{bubbles:true}));await pause(260);assert.equal(db.tasks[0].notes,'Second draft');$('close-drawer').click();await pause(100);w.document.querySelector('[data-open-project]').click();$('notes').innerHTML='Project note';$('notes').dispatchEvent(new w.Event('input',{bubbles:true}));await pause(650);assert.equal(db.projects[0].notes,'Project note');}finally{a.close();}});
test('failed autosave retains the note and blocks closing until a successful retry',async()=>{const a=await setup();try{const {w,db,$}=a,original=w.fetch;w.fetch=async(url,init)=>init.method==='PATCH'?{ok:false,status:503,json:async()=>({message:'Save unavailable'})}:original(url,init);w.document.querySelector('[data-open]').click();$('notes').innerHTML='Do not lose this';$('notes').dispatchEvent(new w.Event('input',{bubbles:true}));$('close-drawer').click();await tick();assert.equal($('drawer').hidden,false);assert.equal($('notes').innerHTML,'Do not lose this');assert.match($('detail-message').textContent,/Could not save/);assert.equal(db.tasks[0].notes,'');w.fetch=original;$('close-drawer').click();await tick();assert.equal(db.tasks[0].notes,'Do not lose this');assert.equal($('drawer').hidden,true);}finally{a.close();}});

test('new task gets only an Assigned square today regardless of selected color',async()=>{const a=await setup();try{const {w,db,p,$}=a;w.document.querySelector('[data-paint="done"]').click();await enterInline(a,'task','New meeting',p);const task=db.tasks.find(t=>t.name==='New meeting'),today=w.document.querySelector('.date-column.today').dataset.day,own=db.cells.filter(c=>c.task_id===task.id);assert.equal(task.status,'assigned');assert.deepEqual(own,[{task_id:task.id,day:today,status:'assigned'}]);assert.match(w.document.querySelector(`[data-owner-id="${task.id}"][data-day="${today}"]`).className,/assigned/);assert.equal(w.document.querySelectorAll(`[data-owner-id="${task.id}"].assigned`).length,1);$('refresh').click();await tick();assert.match(w.document.querySelector(`[data-owner-id="${task.id}"][data-day="${today}"]`).className,/assigned/);}finally{a.close();}});
test('failed task-and-square creation keeps the draft without a partial task',async()=>{const a=await setup();try{const {w,db,$}=a,original=w.fetch;w.fetch=async(url,init)=>url.includes('/rpc/gant02_20261024_create_task')?{ok:false,status:503,json:async()=>({message:'Task creation unavailable'})}:original(url,init);await enterInline(a,'task','Keep this task');assert.equal(db.tasks.length,1);assert.equal(db.cells.length,0);assert.equal(w.document.querySelector('[data-create="task"]').value,'Keep this task');assert.match($('error').textContent,/Task creation unavailable/);}finally{a.close();}});

test('trash icon beside Clear deletes the selected task and its colors',async()=>{const a=await setup();try{const {w,db,$}=a;assert.equal(w.document.querySelector('[data-paint="erase"]').nextElementSibling,$('trash-mode'));let message='';w.confirm=text=>{message=text;return true;};$('trash-mode').click();assert.equal($('trash-mode').getAttribute('aria-pressed'),'true');w.document.querySelector('[data-open]').click();await tick();assert.match(message,/Delete task “Plan launch”/);assert.equal(db.tasks.length,0);assert.equal(db.projects.length,1);assert.equal(w.document.querySelector('.task-row'),null);assert.equal($('trash-mode').getAttribute('aria-pressed'),'false');}finally{a.close();}});
test('trash mode deletes a project with its tasks and date colors',async()=>{const a=await setup();try{const {w,db,$}=a;await enterInline(a,'task','Second task');assert.equal(db.cells.length,1);let message='';w.confirm=text=>{message=text;return true;};$('trash-mode').click();w.document.querySelector('[data-open-project]').click();await tick();assert.match(message,/Delete project “Launch” and all 2 of its tasks/);assert.equal(db.projects.length,0);assert.equal(db.tasks.length,0);assert.equal(db.cells.length,0);assert.equal(w.document.querySelector('.project-row'),null);assert.ok(w.document.querySelector('[data-create="project"]'));}finally{a.close();}});
test('cancel, Escape and color choice leave records safe and exit deletion mode',async()=>{const a=await setup();try{const {w,db,$}=a;w.confirm=()=>false;$('trash-mode').click();w.document.querySelector('[data-open]').click();await tick();assert.equal(db.tasks.length,1);assert.equal($('drawer').hidden,true);const line=w.document.querySelector('.task-timeline');pointer(w,line,'pointerdown',52);pointer(w,line,'pointerup',52);await tick();assert.equal(db.cells.length,0);w.document.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape'}));assert.equal($('trash-mode').getAttribute('aria-pressed'),'false');$('trash-mode').click();w.document.querySelector('[data-paint="done"]').click();assert.equal($('trash-mode').getAttribute('aria-pressed'),'false');w.document.querySelector('[data-open]').click();assert.equal($('drawer').hidden,false);}finally{a.close();}});
test('failed deletion leaves item visible and permits retry',async()=>{const a=await setup();try{const {w,db,$}=a,original=w.fetch;w.fetch=async(url,init)=>init.method==='DELETE'?{ok:false,status:503,json:async()=>({message:'Delete unavailable'})}:original(url,init);$('trash-mode').click();w.document.querySelector('[data-open]').click();await tick();assert.equal(db.tasks.length,1);assert.ok(w.document.querySelector('.task-row'));assert.match($('error').textContent,/Delete unavailable/);assert.equal($('trash-mode').disabled,false);w.fetch=original;w.document.querySelector('[data-open]').click();await tick();assert.equal(db.tasks.length,0);}finally{a.close();}});

test('project/task name hover shows only the next day number or most recent past number',async()=>{const a=await setup();try{const {w,db,p,t,$}=a,today=w.document.querySelector('.date-column.today').dataset.day,task=()=>w.document.querySelector('[data-open]'),project=()=>w.document.querySelector('[data-open-project]');assert.equal(task().title,'');assert.equal(project().title,'');db.cells=[{task_id:t,day:offsetDate(today,-2),status:'assigned'},{task_id:t,day:offsetDate(today,3),status:'done'},{task_id:t,day:offsetDate(today,8),status:'assigned'}];db.project_cells=[{project_id:p,day:offsetDate(today,2),status:'in_progress'}];$('refresh').click();await tick();assert.equal(task().title,'3');assert.equal(project().title,'2');assert.match(w.document.querySelector('.task-timeline [data-index="3"]').title,/^[1-9][0-9]?-[0-9]{2} (Sun|Mon|Tue|Wed|Thu|Fri|Sat) · 3$/);db.cells=db.cells.filter(c=>c.day<today);db.project_cells=[];$('refresh').click();await tick();assert.equal(task().title,'-2');assert.equal(project().title,'-2');}finally{a.close();}});

