test('Android opens a names-only list with visible first-occurrence numbers',async()=>{const a=await setup(true,true);try{const {w,db,p,t,$}=a;assert.ok(w.document.body.classList.contains('android-mode'));assert.equal(w.document.querySelector('header').hidden,true);assert.equal(w.document.querySelector('.toolbar').hidden,true);assert.equal(w.document.querySelector('.bottom').hidden,true);assert.equal(w.document.querySelector('.date-square'),null);assert.equal(w.document.querySelector('.grid-header'),null);assert.equal(w.document.querySelector('[draggable="true"]'),null);assert.equal(w.document.querySelector('.android-project-name').textContent,'Launch');assert.equal(w.document.querySelector('.android-task-name').textContent,'Plan launch');const now=new w.Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;db.cells=[{task_id:t,day:today,status:'assigned'}];db.project_cells=[{project_id:p,day:offsetDate(today,3),status:'assigned'}];$('refresh').click();await tick();assert.equal(w.document.querySelector('.android-project-row .android-days').textContent,'3');assert.equal(w.document.querySelector('.android-task-row .android-days').textContent,'0');}finally{a.close();}});
