test('Android long press opens editable autosaving notes without metadata',async()=>{const a=await setup(true,true);try{const {w,db,$}=a;db.projects[0].notes='<p>Project agenda</p>';$('refresh').click();await tick();let name=w.document.querySelector('.android-project-name');name.click();assert.equal($('drawer').hidden,true);pointer(w,name,'pointerdown',20,20);await pause(600);pointer(w,name,'pointerup',20,20);assert.equal($('drawer').hidden,false);assert.equal($('detail-type').textContent,'Launch');assert.equal($('notes').innerHTML,'<p>Project agenda</p>');assert.equal($('task-fields'),null);assert.equal(w.document.querySelector('.name-label').hidden,true);assert.equal(w.document.querySelector('.editor-tools').hidden,true);assert.equal($('delete-item').hidden,true);$('notes').innerHTML='<p>Updated agenda</p>';$('notes').dispatchEvent(new w.Event('input',{bubbles:true}));await pause(550);assert.equal(db.projects[0].notes,'<p>Updated agenda</p>');$('close-drawer').click();await tick();name=w.document.querySelector('.android-task-name');pointer(w,name,'pointerdown',20,20);await pause(600);pointer(w,name,'pointerup',20,20);assert.equal($('detail-type').textContent,'Plan launch');assert.equal($('drawer').hidden,false);}finally{a.close();}});
test('Android short press, movement and scrolling do not open notes',async()=>{const a=await setup(true,true);try{const {w,$}=a,name=w.document.querySelector('.android-task-name');pointer(w,name,'pointerdown',20,20);pointer(w,name,'pointerup',20,20);await pause(580);assert.equal($('drawer').hidden,true);pointer(w,name,'pointerdown',20,20);pointer(w,name,'pointermove',20,45);await pause(580);assert.equal($('drawer').hidden,true);pointer(w,name,'pointerdown',20,20);$('grid-wrap').dispatchEvent(new w.Event('scroll'));await pause(580);assert.equal($('drawer').hidden,true);}finally{a.close();}});

test('global collapse/expand is beside Complete with a verified Dayflow link',async()=>{const a=await setup();try{const {w,$,copied}=a;await enterInline(a,'project','Second');const done=w.document.querySelector('[data-paint="done"]');assert.equal(done.nextElementSibling,$('collapse-all'));assert.equal($('collapse-all').nextElementSibling,$('dayflow-link'));assert.equal($('dayflow-link').href,'https://esemmelman.github.io/DayFlow/');assert.equal($('dayflow-link').target,'_blank');$('collapse-all').click();assert.equal(w.document.querySelector('.task-row'),null);assert.equal(w.document.querySelectorAll('.project-row').length,2);assert.equal($('collapse-all').getAttribute('aria-expanded'),'false');assert.match($('collapse-all').textContent,/Expand all/);$('collapse-all').click();assert.ok(w.document.querySelector('.task-row'));assert.equal($('collapse-all').getAttribute('aria-expanded'),'true');assert.match($('collapse-all').textContent,/Collapse all/);assert.equal(copied.length,0);}finally{a.close();}});
test('clicking project/task names copies exactly the name and still opens notes',async()=>{const a=await setup();try{const {w,db,$,copied}=a;db.projects[0].name='Launch <&> project';db.tasks[0].name='Buy supplies';$('refresh').click();await tick();w.document.querySelector('[data-open-project]').click();await tick();assert.equal(copied[0],'Launch <&> project');assert.equal($('drawer').hidden,false);$('close-drawer').click();await tick();w.document.querySelector('[data-open]').click();await tick();assert.deepEqual(copied,['Launch <&> project','Buy supplies']);assert.equal($('drawer').hidden,false);}finally{a.close();}});
test('Android tap copies a name, while long press opens notes without copying again',async()=>{const a=await setup(true,true);try{const {w,$,copied}=a;let name=w.document.querySelector('.android-task-name');name.click();await tick();assert.deepEqual(copied,['Plan launch']);assert.equal($('drawer').hidden,true);pointer(w,name,'pointerdown',20,20);await pause(600);pointer(w,name,'pointerup',20,20);name.click();await tick();assert.deepEqual(copied,['Plan launch']);assert.equal($('drawer').hidden,false);}finally{a.close();}});
test('clipboard fallback copies the name and denied copying never blocks notes',async()=>{const a=await setup();try{const {w,$}=a;w.navigator.clipboard.writeText=async()=>{throw Error('Denied');};let copiedText='';w.document.execCommand=command=>{assert.equal(command,'copy');copiedText=w.document.querySelector('textarea').value;return true;};w.document.querySelector('[data-open]').click();await tick();assert.equal(copiedText,'Plan launch');assert.equal(w.document.querySelector('textarea'),null);assert.equal($('drawer').hidden,false);$('close-drawer').click();await tick();w.document.execCommand=()=>false;w.document.querySelector('[data-open-project]').click();await tick();assert.equal($('drawer').hidden,false);assert.match($('toast').textContent,/Could not copy/);}finally{a.close();}});

test('multiple comment entries autosave independently and leave the rich note intact',async()=>{const a=await setup();try{const {w,db,$}=a;db.tasks[0].notes='<p>Original rich note</p>';$('refresh').click();await tick();w.document.querySelector('[data-open]').click();await tick();assert.equal($('new-comment').disabled,false);$('new-comment').click();let input=w.document.querySelector('[data-comment-id]');input.value='First comment';input.dispatchEvent(new w.Event('input',{bubbles:true}));await pause(550);assert.equal(db.comments.length,1);assert.equal(db.comments[0].body,'First comment');const firstId=db.comments[0].id;$('new-comment').click();input=w.document.querySelector('[data-comment-id]');input.value='Second comment';input.dispatchEvent(new w.Event('input',{bubbles:true}));$('close-drawer').click();await tick();assert.equal(db.comments.length,2);assert.equal(db.tasks[0].notes,'<p>Original rich note</p>');assert.equal($('drawer').hidden,true);w.document.querySelector('[data-open]').click();await tick();assert.equal(w.document.querySelectorAll('.comment-entry').length,2);assert.ok(w.document.querySelector('time').dateTime);input=w.document.querySelector(`[data-comment-id="${firstId}"]`);input.value='First comment updated';input.dispatchEvent(new w.Event('input',{bubbles:true}));await pause(550);assert.equal(db.comments.length,2);assert.equal(db.comments.find(c=>c.id===firstId).body,'First comment updated');}finally{a.close();}});
