test('failed comment autosave retains the entry and retries when closing',async()=>{const a=await setup();try{const {w,db,$}=a,original=w.fetch;w.fetch=async(url,init)=>url.includes('_comments')&&init.method==='POST'?{ok:false,status:503,json:async()=>({message:'Comment save unavailable'})}:original(url,init);w.document.querySelector('[data-open]').click();await tick();$('new-comment').click();let input=w.document.querySelector('[data-comment-id]');input.value='Keep this comment';input.dispatchEvent(new w.Event('input',{bubbles:true}));$('close-drawer').click();await tick();assert.equal($('drawer').hidden,false);assert.equal(w.document.querySelector('[data-comment-id]').value,'Keep this comment');assert.match(w.document.querySelector('.comment-status').textContent,/Could not save/);assert.equal(db.comments.length,0);w.fetch=original;$('close-drawer').click();await tick();assert.equal(db.comments[0].body,'Keep this comment');assert.equal($('drawer').hidden,true);}finally{a.close();}});
test('Android long-press note panel supports multiple comment entries',async()=>{const a=await setup(true,true);try{const {w,db,$}=a,name=w.document.querySelector('.android-task-name');pointer(w,name,'pointerdown',20,20);await pause(600);pointer(w,name,'pointerup',20,20);await tick();$('new-comment').click();let input=w.document.querySelector('[data-comment-id]');input.value='Android comment one';input.dispatchEvent(new w.Event('input',{bubbles:true}));$('new-comment').click();input=w.document.querySelector('[data-comment-id]');input.value='Android comment two';input.dispatchEvent(new w.Event('input',{bubbles:true}));$('close-drawer').click();await tick();assert.equal(db.comments.length,2);assert.ok(db.comments.every(c=>c.task_id===db.tasks[0].id));assert.equal($('drawer').hidden,true);}finally{a.close();}});

test('dragging a colored square displays destination date and numeric days out',async()=>{const a=await setup();try{const {w,$}=a;const line=w.document.querySelector('.task-timeline');pointer(w,line,'pointerdown',52);pointer(w,line,'pointerup',52);await tick();const source=w.document.querySelector('.task-timeline [data-index="2"]'),target=w.document.querySelector('.project-row [data-index="5"]'),event=new w.MouseEvent('dragstart',{bubbles:true,clientX:100,clientY:120});event.dataTransfer={setData(){}};source.dispatchEvent(event);assert.equal($('square-drag-hint').hidden,false);assert.equal($('square-drag-hint').textContent,source.title);const over=new w.MouseEvent('dragover',{bubbles:true,cancelable:true,clientX:200,clientY:180});over.dataTransfer={};target.dispatchEvent(over);assert.equal($('square-drag-hint').textContent,target.title);assert.match($('square-drag-hint').textContent,/ · 5$/);target.dispatchEvent(new w.MouseEvent('drop',{bubbles:true,cancelable:true}));await tick();assert.equal($('square-drag-hint').hidden,true);}finally{a.close();}});

test('Android task text follows today square color and stays neutral for other dates',async()=>{const a=await setup(true,true);try{const {w,db,t,$}=a,now=new w.Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;for(const status of ['assigned','in_progress','done']){db.cells=[{task_id:t,day:today,status}];$('refresh').click();await tick();assert.ok(w.document.querySelector('.android-task-row').classList.contains('android-today-'+status));assert.equal(w.document.querySelector('.android-task-row .android-days').textContent,'0');}db.cells=[{task_id:t,day:offsetDate(today,3),status:'done'}];$('refresh').click();await tick();assert.doesNotMatch(w.document.querySelector('.android-task-row').className,/android-today-/);db.cells=[{task_id:t,day:today,status:null}];$('refresh').click();await tick();assert.doesNotMatch(w.document.querySelector('.android-task-row').className,/android-today-/);}finally{a.close();}});

function quickType(a,text){a.$('quick-task-input').value=text;a.$('quick-task-input').dispatchEvent(new a.w.Event('input',{bubbles:true}));}
function mockSpeech(w){const instances=[];w.webkitSpeechRecognition=class{constructor(){instances.push(this);}start(){this.started=true;}stop(){this.stopped=true;this.onend?.();}};return instances;}
test('Android top capture adds typed tasks to General with today assigned',async()=>{const a=await setup(true,true);try{const {w,db,$}=a;assert.equal(w.document.querySelector('.android-list').firstElementChild.className,'android-quick-entry');assert.equal($('quick-add').disabled,true);quickType(a,'Call the dentist');$('quick-add').click();await tick();const general=db.projects.find(p=>p.name==='General'),task=db.tasks.find(t=>t.name==='Call the dentist');assert.ok(general);assert.equal(task.project_id,general.id);assert.equal(task.start_date,task.end_date);assert.deepEqual(db.cells.find(c=>c.task_id===task.id),{task_id:task.id,day:task.start_date,status:'assigned'});assert.equal($('quick-task-input').value,'');assert.match($('quick-message').textContent,/Added to General/);quickType(a,'Buy supplies');$('quick-task-input').dispatchEvent(new w.KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));await tick();assert.equal(db.projects.filter(p=>p.name==='General').length,1);assert.equal(db.tasks.filter(t=>t.project_id===general.id).length,2);}finally{a.close();}});
test('one tap starts voice capture and interim transcripts do not duplicate words',async()=>{const a=await setup(true,true);try{const {w,db,$}=a,voices=mockSpeech(w);$('quick-task-input').click();assert.equal(voices.length,1);assert.equal(voices[0].started,true);assert.equal(voices[0].interimResults,true);assert.equal($('quick-mic').getAttribute('aria-pressed'),'true');voices[0].onresult({results:[[{transcript:'Call'}]]});assert.equal($('quick-task-input').value,'Call');voices[0].onresult({results:[[{transcript:'Call the dentist'}]]});assert.equal($('quick-task-input').value,'Call the dentist');voices[0].onend();assert.equal($('quick-mic').getAttribute('aria-pressed'),'false');$('quick-add').click();await tick();assert.ok(db.tasks.some(t=>t.name==='Call the dentist'));assert.equal(db.projects.find(p=>p.id===db.tasks.find(t=>t.name==='Call the dentist').project_id).name,'General');}finally{a.close();}});
test('unsupported or denied voice capture still allows typed tasks',async()=>{const a=await setup(true,true);try{const {w,db,$}=a;$('quick-mic').click();assert.match($('quick-message').textContent,/unavailable/);const voices=mockSpeech(w);$('quick-mic').click();voices[0].onerror({error:'not-allowed'});assert.match($('quick-message').textContent,/blocked/);assert.equal($('quick-task-input').disabled,false);quickType(a,'Typed fallback');$('quick-add').click();await tick();assert.ok(db.tasks.some(t=>t.name==='Typed fallback'));}finally{a.close();}});
test('failed quick capture retains text and request ID for a safe retry',async()=>{const a=await setup(true,true);try{const {w,db,$}=a,original=w.fetch,requests=[];let fail=true;w.fetch=async(url,init)=>{if(url.includes('/rpc/gant02_20261024_quick_add')){requests.push(JSON.parse(init.body).p_task_id);if(fail)return {ok:false,status:503,json:async()=>({message:'Capture unavailable'})};}return original(url,init);};quickType(a,'Retry this capture');$('quick-add').click();await tick();assert.equal($('quick-task-input').value,'Retry this capture');assert.match($('quick-message').textContent,/Capture unavailable/);assert.equal(db.projects.some(p=>p.name==='General'),false);fail=false;$('quick-add').click();await tick();assert.equal(requests[0],requests[1]);assert.equal(db.tasks.filter(t=>t.name==='Retry this capture').length,1);assert.equal($('quick-task-input').value,'');}finally{a.close();}});
test('voice stop and manual edits retain the latest text; desktop has no capture box',async()=>{const a=await setup(true,true);try{const {w,$}=a,voices=mockSpeech(w);$('quick-mic').click();voices[0].onresult({results:[[{transcript:'Draft voice text'}]]});quickType(a,'Edited text');assert.equal(voices[0].stopped,true);voices[0].onresult({results:[[{transcript:'Late voice result'}]]});assert.equal($('quick-task-input').value,'Edited text');$('quick-mic').click();assert.equal(voices.length,2);$('quick-mic').click();assert.equal(voices[1].stopped,true);}finally{a.close();}const desktop=await setup();try{assert.equal(desktop.$('quick-task-input'),null);}finally{desktop.close();}});

test('desktop has an independent New project field directly above each New task field',async()=>{const a=await setup();try{const {w,db}=a;for(const taskInput of w.document.querySelectorAll('[data-create="task"]')){const row=taskInput.closest('.row'),previous=row.previousElementSibling;assert.ok(previous.classList.contains('new-project-row'));assert.equal(previous.querySelector('input').dataset.create,'project');}const input=w.document.querySelector('[data-create="project"]');input.value='Created above task';input.dispatchEvent(new w.Event('input',{bubbles:true}));input.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));await tick();assert.ok(db.projects.some(p=>p.name==='Created above task'));assert.equal(db.tasks.length,1);}finally{a.close();}});

function selectView(a,value){a.$('view-scale').value=value;a.$('view-scale').dispatchEvent(new a.w.Event('change'));}
test('view dropdown is before previous and Today with Daily as the default',async()=>{const a=await setup();try{const {w,$}=a;assert.equal($('view-scale').nextElementSibling,$('prev'));assert.equal($('prev').nextElementSibling,$('today'));assert.deepEqual([...$('view-scale').options].map(x=>x.textContent),['Daily','Weekly','Monthly']);assert.equal($('view-scale').value,'daily');assert.equal($('grid').dataset.view,'daily');assert.equal(w.document.querySelector('.date-column').dataset.day,w.document.querySelector('.date-column.today').dataset.day);}finally{a.close();}});
test('Weekly and Monthly use wider horizons with month/week grouping and day density',async()=>{const a=await setup();try{const {w,$}=a;const first=w.document.querySelector('.date-column').dataset.day;selectView(a,'weekly');assert.equal($('grid').dataset.view,'weekly');assert.equal(w.document.querySelectorAll('.mini-day').length,182);assert.equal(w.document.querySelectorAll('.task-timeline .date-square').length,182);assert.equal(w.document.documentElement.style.getPropertyValue('--day'),'12px');assert.equal(w.document.querySelector('.mini-day').dataset.day,first);assert.ok(w.document.querySelectorAll('.scale-week').length>20);selectView(a,'monthly');assert.equal(w.document.querySelectorAll('.mini-day').length,366);assert.equal(w.document.documentElement.style.getPropertyValue('--day'),'5px');const months=[...w.document.querySelectorAll('.scale-month')];assert.equal(months.reduce((sum,m)=>sum+Number(m.dataset.days),0),366);assert.equal(months.reduce((sum,m)=>sum+parseFloat(m.style.width),0),366*5);$('zoom').value='detailed';$('zoom').dispatchEvent(new w.Event('change'));assert.equal(w.document.documentElement.style.getPropertyValue('--day'),'9px');assert.equal(w.document.querySelectorAll('.mini-day').length,366);selectView(a,'daily');assert.equal(w.document.querySelectorAll('.date-column').length,120);assert.equal(w.document.documentElement.style.getPropertyValue('--day'),'40px');}finally{a.close();}});
test('color painting and moving retain exact dates in weekly/monthly views',async()=>{const a=await setup();try{const {w,db,$}=a;selectView(a,'weekly');let line=w.document.querySelector('.task-timeline'),target=w.document.querySelector('.task-timeline [data-index="3"]'),day=target.dataset.day;pointer(w,line,'pointerdown',3*12+1);pointer(w,line,'pointerup',3*12+1);await tick();assert.equal(db.cells.find(c=>c.day===day).status,'assigned');selectView(a,'monthly');const source=w.document.querySelector('.task-timeline [data-index="3"]'),dest=w.document.querySelector('.task-timeline [data-index="8"]'),newDay=dest.dataset.day;assert.match(source.className,/assigned/);dragItem(w,source,dest);await tick();assert.equal(db.cells.find(c=>c.day===day).status,null);assert.equal(db.cells.find(c=>c.day===newDay).status,'assigned');selectView(a,'daily');assert.match(w.document.querySelector('.task-timeline [data-index="8"]').className,/assigned/);}finally{a.close();}});
test('scale navigation moves a week or calendar month and Today restores today',async()=>{const a=await setup();try{const {w,$}=a,initial=w.document.querySelector('.date-column').dataset.day;selectView(a,'weekly');$('next').click();assert.equal(w.document.querySelector('.mini-day').dataset.day,offsetDate(initial,7));$('prev').click();assert.equal(w.document.querySelector('.mini-day').dataset.day,initial);selectView(a,'monthly');$('next').click();const shifted=w.document.querySelector('.mini-day').dataset.day;assert.notEqual(shifted.slice(0,7),initial.slice(0,7));$('today').click();assert.equal(w.document.querySelector('.mini-day').dataset.day,initial);assert.equal(w.shiftCalendarMonth('2026-01-31',1),'2026-02-28');assert.equal(w.shiftCalendarMonth('2028-01-31',1),'2028-02-29');assert.equal(w.shiftCalendarMonth('2026-12-31',1),'2027-01-31');}finally{a.close();}});
